/* xx_mpq_extractor.c - search raw data for MPQ.
 *
 * Scans for:
 *   4D 50 51 1A at +0  ("MPQ.")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the mpq reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/mpq/xx_mpq.h"

static const uint8_t k_anchor0[] = { 0x4D, 0x50, 0x51, 0x1A };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_MPQ };

static Abstractformat *xx_mpq_search_open(xx_io_device *window) {
    xx_mpq *reader = xx_mpq_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_mpq_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_mpq_free((xx_mpq *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_mpq_search_open, xx_mpq_search_close
};

static xx_format_search_state *xx_mpq_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_mpq_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_mpq_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_mpq_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_mpq_extractor = {
    xx_mpq_create_format_search,
    xx_mpq_get_current_format_info,
    xx_mpq_format_search_find_next,
    xx_mpq_free_format_search
};
